const NL = String.fromCharCode(10);
function txt(s) {
  return String(s || '').replace(/<br\s*\/?>/gi, NL).replace(/<\/p>/gi, NL).replace(/<[^>]+>/g, '')
    .replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>')
    .replace(/&eacute;/g, 'e').replace(/&egrave;/g, 'e').replace(/&agrave;/g, 'a').replace(/&ucirc;/g, 'u').replace(/&rsquo;/g, "'").replace(/&[a-z]+;/g, ' ')
    .replace(/[ \t]+/g, ' ').replace(/(\r?\n\s*){2,}/g, NL).trim();
}
function d(x) { const t = DateTime.fromISO(String(x || ''), { zone: 'utc' }); return t.isValid ? t.setZone('Europe/Paris').toFormat('dd/MM/yyyy') : '?'; }
function premier(n) { try { return $(n).first().json || {}; } catch (e) { return {}; } }
const A = [];
const fiche = premier('Lire fiche');
let aFiche = false;
if (fiche.ok && fiche.data) {
  const c = fiche.data;
  const parts = [txt(c.commentary)].concat(Object.values(c.additionalData || {}).map(txt)).filter(x => x && !/^(france|monaco)$/i.test(x));
  if (parts.length) { A.push('FICHE CLIENT (notes internes) : ' + parts.join(' | ').slice(0, 1200)); aFiche = true; }
}
const act = premier('Lire activites');
const acts = (act.ok && act.data && act.data.items) || [];
const notes = [], mails = [];
for (const a of acts) {
  const dt = d(a.date);
  const da = a.data || {};
  if (a.type === 'email' || a.type === 'sms') {
    const s = da.subject || txt(da.body).slice(0, 120);
    if (s) mails.push('- ' + dt + ' ' + a.type + ' : ' + s);
  } else {
    const c = txt(da.content);
    if (c) notes.push('- ' + dt + ' (' + (a.type === 'call' ? 'appel' : 'note') + ') ' + c.slice(0, 4000));
  }
}
const rap = [];
let rapAll = [];
try { rapAll = $('Lire rapports').all(); } catch (e) {}
for (const it of rapAll) {
  const r = it.json || {};
  if (!r.ok || !r.data) continue;
  const x = r.data;
  const L = ['- ' + d(x.startDate || x.date) + ' ' + [x.title, x.type].filter(Boolean).join(' / ')];
  const desc = txt(x.description);
  if (desc) L.push('  Consigne RDV : ' + desc.slice(0, 400));
  for (const rp of (x.reports || [])) {
    let rd = {};
    try { rd = typeof rp.reportData === 'string' ? JSON.parse(rp.reportData) : (rp.reportData || {}); } catch (e) {}
    const champs = [
      ['Travaux', rd.comments],
      ['Remarque technicien', rd.technicianComment],
      ['Remarque client', rd.clientComment],
      ['A replanifier', rd.scheduleOtherIntervention ? (rd.scheduleOtherInterventionComment || 'oui') : ''],
      ['Devis a prevoir', (rd.forecastingCostEstimates || rp.needAQuotation) ? (rd.forecastingCostEstimatesComment || 'oui') : ''],
      ['Client absent', rd.clientNotHere ? 'oui' : '']
    ];
    for (const [k, v] of champs) { const t = txt(v); if (t) L.push('  ' + k + ' : ' + t.slice(0, 800)); }
  }
  const eq = (x.equipments || []).map(e => [e.name, e.brand, e.model, e.serialNumber].filter(Boolean).join(' ')).filter(Boolean);
  if (eq.length) L.push('  Equipements : ' + eq.join(', ').slice(0, 300));
  rap.push(L.join(NL));
}
if (notes.length) A.push('NOTES ET APPELS CONSIGNES (plus recent en premier) :' + NL + notes.join(NL));
if (rap.length) A.push('INTERVENTIONS PASSEES (plus recente en premier) :' + NL + rap.join(NL));
if (mails.length) A.push('EMAILS ET SMS ENVOYES PAR CLIMATPRO :' + NL + mails.slice(0, 15).join(NL));
const vide = !aFiche && !notes.length && !rap.length && !mails.length;
return [{ json: { vide, contexte: A.join(NL + NL).slice(0, 24000) } }];

const NL = String.fromCharCode(10);
let t = '';
try { t = ($input.first().json.content || []).map(c => c.text || '').join('').trim(); } catch (e) {}
let o = {};
try { const a = t.indexOf('{'), b = t.lastIndexOf('}'); o = JSON.parse(t.slice(a, b + 1)); } catch (e) { o = { tech: '', admin: t }; }
const BAN = /\u20ac|\beur\b|euro|prix|tarif|remise|factur|impay|budget|marge|n[e\u00e9]goci|montant|ristourne|\bht\b|\bttc\b|galer/i;
const VIDE = /^-?\s*(aucun|aucune|rien|pas de)\b/i;
const lignes = s => String(s || '').replace(/[\u2013\u2014]/g, '-').split(/\r?\n/).map(x => x.trim()).filter(x => x && !VIDE.test(x));
const tech = lignes(o.tech).filter(l => !BAN.test(l)).slice(0, 6).join(NL);
const admin = lignes(o.admin).filter(l => !/intervention pr[e\u00e9]vue/i.test(l)).slice(0, 8).join(NL);
return [{ json: { eventId: String($('Entree').first().json.eventId || ''), tech, admin } }];

const h = $input.first().json || {};
const evId = String($('Entree').first().json.eventId || '');
const items = (h.ok && h.data && h.data.items) || [];
const now = Date.now();
const passes = items.filter(e => (e.category || 'intervention') === 'intervention' && e.finished && String(e.id) !== evId && new Date(e.start).getTime() < now)
  .sort((a, b) => String(b.start).localeCompare(String(a.start)))
  .slice(0, 6);
return passes.length ? passes.map(e => ({ json: { id: String(e.id) } })) : [{ json: { id: 'aucune' } }];
